import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2018-pm-health-facts.json';
export function legacy2018HealthMasterTruth(variant:number,regular:boolean,selected:readonly string[]){const have=new Set(['employeeId','pastPlace']);if(regular||selected.includes('E'))for(const k of['age','sex','positionCode','currentWorkCode'])have.add(k);if(selected.includes('P')&&have.has('positionCode'))have.add('managerFlag');if(selected.includes('W')&&have.has('currentWorkCode'))have.add('currentPlace');return have.has('currentPlace')&&(!regular||have.has('age')&&have.has('sex')&&(variant===1||have.has('managerFlag')));}
export function legacy2018HealthOracle(body:GeneratedBody,values:readonly number[]){assert.equal(values.length,1);const variant=values[0];assert(variant===0||variant===1);assert.equal(body.prompt.length,52);assert.equal(facts.sourceUnits.length,54);assert.equal(facts.sourceUnitMapping.flatMap(x=>x.sourceUnitIndices).length,54);for(let i=0;i<52;i++){const actual=body.prompt[i],u=facts.bodyUnits[i];if(u.kind==='table'){assert.equal(actual.type,'table');assert(actual.type==='table');const expected=structuredClone(facts.table);if(variant)expected.rows[2][1]=expected.rows[2][1].replace('従業員の年齢，性別，管理職かどうか','従業員の年齢及び性別だけ');assert.deepEqual(actual,{type:'table',...expected});}else if(u.kind==='figure'){assert.equal(actual.type,'diagram');assert(actual.type==='diagram'&&actual.scene.kind==='source_figure');assert.equal(actual.scene.profile,u.profile);assert.deepEqual(actual.scene.values,[0]);assert.equal(actual.caption,u.caption);assert.equal(actual.alt,u.alt);}else{assert(actual.type==='paragraph');assert.equal(actual.text,u.text);}}
 const expected=[...facts.choices.ab,...facts.choices.c,...facts.choices.d,...facts.choices.e];assert.deepEqual(body.choices,expected.map(text=>[{type:'paragraph',text}]));const truth=facts.truth[variant],keys=[truth.a.findIndex(x=>x.truth),truth.b.findIndex(x=>x.truth),...['c','d','e'].map(part=>facts.batchSinglePartTruths.filter(x=>x.part===part).findIndex(x=>x.truth))],offset=[0,0,10,16,20],counts=[10,10,6,4,5];assert.deepEqual(keys,variant?[9,2,2,0,3]:[6,2,2,0,3]);const names=['a','b','c','d','e'];assert.deepEqual(body.answerParts,names.map((n,i)=>({id:'part-'+n,label:facts.partLabels[i],choiceIds:Array.from({length:counts[i]},(_,j)=>'choice-value-'+(offset[i]+j+1))})));assert.deepEqual(body.partAnswers,names.map((n,i)=>({kind:'choice',partId:'part-'+n,choiceId:'choice-value-'+(offset[i]+keys[i]+1)})));assert.equal(body.correctIndex,undefined);assert(body.explanation.includes(variant?'年齢と性別だけ':'職位マスタ及び在勤地マスタ'));for(const phrase of['対象年','判定結果が空白','再検査要否が要','現在の在勤地','区分','コース'])assert(body.explanation.includes(phrase));return{truth:[...truth.a.map(x=>x.truth),...truth.b.map(x=>x.truth),...facts.batchSinglePartTruths.map(x=>x.truth)],keys};}
export type HealthRecord={employee:number;target:number;month:number;kind:'regular'|'recheck';course:string;result:string;need:string};
export function legacy2018HealthBusinessMissing(employee:number,rows:readonly HealthRecord[],target=2018){const rs=rows.filter(r=>r.employee===employee&&r.target===target),r=rs.find(r=>r.kind==='regular');if(!r||!r.result)return true;if(r.need!=='yes')return false;const re=rs.filter(r=>r.kind==='recheck');return !re.length||re.some(r=>!r.result);}
export function legacy2018HealthBatch(rows:readonly HealthRecord[],target=2018){const sorted=rows.filter(r=>r.target===target).slice().sort((a,b)=>a.employee-b.employee||b.month-a.month),latest=sorted.filter((r,i)=>i===0||sorted[i-1].employee!==r.employee);return latest;}
